# Lonsurf: retain audited v4 rules, add previously missing safeguards.
l=json.loads((OUT/'00382-before.json').read_text())
for k,label in [('hereditary_sugar_disorder','Rare hereditary galactose intolerance, total lactase deficiency or glucose-galactose malabsorption'),('dose_reescalation_requested','Proposed increase after a prior Lonsurf dose reduction'),('reduction_required_now','A further 5 mg/m² per-dose reduction is required'),('toxicity_recovered_grade1_or_baseline','Prior dose-limiting toxicity recovered to grade 1 or baseline'),('restart_after_toxicity','Considering restart after dose-limiting toxicity'),('unable_tolerate_severe_renal_minimum','Unable to tolerate 15 mg/m² twice daily in severe renal impairment'),('lonsurf_interacting_medicine','Thymidine-kinase substrate (e.g. zidovudine), nucleoside-transporter, OCT2 or MATE1 interaction'),('prior_crc_therapy_eligibility_unmet','Prior CRC treatment / suitability criteria not met'),('planned_tablets_verified','Oncology pharmacy has verified BSA band and morning/evening tablets')]:addinput(l,k,label)
num(l,'prior_dose_reductions','Number of previous Lonsurf dose reductions',0,10,1)
num(l,'bsa_m2','Body surface area (m²); source-table tablet verification only',0.1,4)
num(l,'planned_total_daily_dose_mg','Planned total daily trifluridine dose (mg)',0,200)
rule(l,'EXCLUSION_SUGAR_DISORDER',yes('hereditary_sugar_disorder'),'contraindicated','Lonsurf contains lactose: patients with these rare hereditary disorders should not take it. This does not equate ordinary lactose-related symptoms with the specified disorders.',5,'Regimen-specific complications')
rule(l,'PRIOR_THERAPY_REVIEW',yes('prior_crc_therapy_eligibility_unmet'),'consultant_review','Confirm previous treatment or non-candidacy for available fluoropyrimidine, oxaliplatin, irinotecan, anti-VEGF and anti-EGFR therapies for NCCP 00382a.',1,'Indications')
rule(l,'NO_REESCALATION',yes('dose_reescalation_requested'),'withhold','Do not increase Lonsurf after a dose reduction. Reconcile the proposed prescription with actual prior dose history before administration.',2,'Dose modifications; Table 7 p4')
rule(l,'MAX_REDUCTIONS',ANY(c('prior_dose_reductions','>',3),ALL(yes('reduction_required_now'),c('prior_dose_reductions','>=',3))),'withhold','A maximum of three standard reductions is permitted, with minimum 20 mg/m² twice daily. A further reduction is outside this pathway; obtain a consultant alternative/stop plan. Severe renal dosing has its separate 20→15 mg/m² pathway.',2,'Dose modifications')
rule(l,'DOSE_HISTORY_REQUIRED',ALL(yes('reduction_required_now'),ANY(missing('current_dose_mg_m2_bd'),missing('prior_dose_reductions'))),'consultant_review','Confirm actual current dose, prior reductions and renal pathway before prescribing another reduction; never calculate from the original 35 mg/m² reference dose.',2,'Dose modifications / Tables 3–6')
renal_severe=ANY(ALL(c('lonsurf_crcl_ml_min','>=',15),c('lonsurf_crcl_ml_min','<',30)),ALL(c('crcl_ml_min','>=',15),c('crcl_ml_min','<',30)))
rule(l,'SEVERE_RENAL_MINIMUM_STOP',yes('unable_tolerate_severe_renal_minimum'),'discontinue','Patients unable to tolerate 15 mg/m² twice daily in severe renal impairment should discontinue Lonsurf.',5,'SmPC 4.2',True)
rule(l,'SEVERE_RENAL_REDUCTION_LIMIT',ALL(renal_severe,yes('reduction_required_now'),c('current_dose_mg_m2_bd','==','15')),'withhold','Already at the severe-renal minimum 15 mg/m² twice daily: do not reduce to 10 mg/m². If this minimum is not tolerated, the SmPC advises discontinuation.',4,'Table 6; EMA 4.2 p5')
rule(l,'STANDARD_DOSE_FLOOR',ALL(yes('reduction_required_now'),c('current_dose_mg_m2_bd','==','20'),ANY(c('lonsurf_crcl_ml_min','>=',30),c('crcl_ml_min','>=',30))),'withhold','At the standard minimum 20 mg/m² twice daily, another 5 mg/m² reduction is not authorised. The 15 mg/m² minimum belongs only to the severe-renal pathway.',2,'Dose modifications; Tables 4 and 6')
rule(l,'RESTART_RECOVERY_UNCONFIRMED',ALL(yes('restart_after_toxicity'),no_or_missing('toxicity_recovered_grade1_or_baseline')),'withhold','After a dose-limiting event, hold until toxicity is grade 1 or baseline and the applicable blood-count recovery criteria are met. Grade 2 is not sufficient; missing recovery is not normal.',3,'Table 3; Table 7 p4')
rule(l,'RENAL_CONTEXT_CONFLICT',ANY(ALL(c('lonsurf_crcl_ml_min','>=',30),c('crcl_ml_min','<',30)),ALL(c('lonsurf_crcl_ml_min','<',30),c('crcl_ml_min','>=',30))),'consultant_review','Exact creatinine clearance and the legacy renal-band entry disagree across the 30 mL/min treatment boundary. Reconcile the measurement/date and renal pathway; no automatic dose selection.',4,'Table 5; input-conflict safeguard')
rule(l,'ASSESSMENT_CONTEXT_CONFLICT',ANY(ALL(c('assessment_type','==','on_treatment'),c('assessment_context','==','start_next_cycle')),ALL(c('assessment_type','in',['pre_treatment','restart']),c('assessment_context','==','during_cycle'))),'consultant_review','Assessment timing entries disagree. Resolve during-cycle interruption versus new-cycle/restart eligibility; the more restrictive actionable blood-count finding remains in force.',2,'Table 2; input-conflict safeguard')
rule(l,'INTERACTION_REVIEW',yes('lonsurf_interacting_medicine'),'consultant_review','Review with oncology pharmacy. Zidovudine and other thymidine-kinase substrates may lose antiviral efficacy; transporter/OCT2/MATE1 interactions also need assessment. Do not infer a numerical Lonsurf reduction.',8,'SmPC 4.5',True)
rule(l,'SPECIAL_50MG_DAILY_PLAN',c('planned_total_daily_dose_mg','==',50),'consultant_review','At a source-table total of 50 mg daily, give 20 mg in the morning and 30 mg in the evening (two 15 mg tablets), not 25 mg twice daily. Verify the applicable BSA/dose/renal band with pharmacy.',3,'Table 4 footnote; Table 6 p4')
rule(l,'TABLET_PLAN_UNVERIFIED',ALL(ANY(c('bsa_m2','exists'),c('planned_total_daily_dose_mg','exists')),no_or_missing('planned_tablets_verified')),'consultant_review','Use the applicable NCCP BSA tablet table; do not substitute arithmetic rounding, exceed the 80 mg per-dose starting cap or assume identical AM/PM tablet counts. Pharmacy must confirm the complete plan.',1,'Tables 1, 4 and 6')
# Keep source-based governance explicit; label before/after change and retained independent review requirement.
for field in ['hfsr_grade','hypertension_grade','other_toxicity_grade']:
 d=p['input_definitions'][field]
 for key in ['ctcae_version','ctcae_category','ctcae_source_url']:d.pop(key,None)
 d.update(demo_value='',grading_source_url=p['metadata']['source_url'],grading_source_label='NCCP 00244 v5 Table 4 (CTCAE 4.03)' if field=='hypertension_grade' else 'NCCP 00244 v5 source table; grading edition not specified',source_grading_note='Apply the named toxicity and source table; this is not a complete grading table. Table 4 cites CTCAE 4.03 and retains a disputed >200 mmHg diastolic-rise string; do not substitute a guessed criterion.' if field=='hypertension_grade' else 'Apply the named toxicity and NCCP source severity; no CTCAE v5 substitution. This is not a complete grading table.')
 if field=='hypertension_grade':d['ctcae_version']='4.03'
 if field=='hfsr_grade':d['options']=[v for v in d['options'] if v['value']!=4]
 for option in d['options']:
  option.pop('ctcae_grade',None)
  if field!='hypertension_grade':option['description']='Use the named toxicity-specific grading and NCCP table; grade 0 is explicitly absent, not unknown.'
for q in [p,l]:
 code=q['metadata']['nccp_regimen_code'];m=q['metadata']
 m.update(sactcheck_encoding_version='0.84.34',source_checked_date='2026-11-05',source_retrieval_method='Current official HSE PDF retrieved with curl; dose tables visually checked; current EMA supplement archived',source_pdf_sha256=hashlib.sha256((OUT/(code+'.pdf')).read_bytes()).hexdigest(),source_text_snapshot_sha256=hashlib.sha256((OUT/(code+'.txt')).read_bytes()).hexdigest())
 m['validation'].update(source_document_checked=True,source_reconciled=True,rule_level_source_reconciliation_status='source_reconciled_v08434_independent_review_pending',consultant_reviewed=False,oncology_pharmacy_reviewed=False,clinical_use_authorised=False)
 m['encoding_maturity'].update(level='source_reconciled_pending_independent_review',label='Source reconciled · independent clinical and pharmacy review pending',source_reconciled=True,audit_release='0.84.34',audit_date='2026-11-05',reconciled_release='0.84.34',reconciled_date='2026-11-05',scope_note='Current source-to-rule reconciliation and engine boundary cases in validation/colorectal-v08434/oral-source-audit. Retained source ambiguities and manually assessed domains are explicit. Independent clinical and pharmacy validation remains pending.')
 m['source_supplements']=[{'label':'EMA product information, current retrieved copy','url':EMA[code],'retrieved_date':'2026-11-05','basis':'Explicit supplement where NCCP refers to the SmPC; no inferred NCCP threshold'}]
 q['rule_engine']['missing_data_policy']='Do not infer missing values, recovery, recurrence, current dose, reduction history or clinical context. Entered independent stop/hold findings remain actionable. No automatic patient-specific dose is calculated from a reference dose.'
 for v in q['input_definitions'].values():v['required']=False
 q['required_inputs']=[]
 (ROOT/'protocols/gastrointestinal'/q['file_name']).write_text(json.dumps(q,indent=2,ensure_ascii=False)+'\n')
 print(code,len(q['input_definitions']),'inputs',len(q['rule_engine']['rules']),'rules')
